step("A1 open Actions panel, initial 4/4 steps and 0.1740 m3","await h.actions();const s=await h.stepsNow(s=>s.n===4,150000,'demo steps loaded');h.ok(s&&s.k===4&&s.n===4&&Math.abs(s.vol-0.174)<1e-3,'initial '+h.json(s));window.__v0=s.vol;return h.json(s)",timeoutMs=170000)
