step("A12 Undo restores removed step","h.click('Undo');const s=await h.stepsNow(s=>s.n===4,75000,'n=4');await h.until(()=>h.labels().includes('Insert Dowel'),75000,'row back');return h.json(s)")
step("A13 select row then Remove Selected Step","h.click('Drill Dowel Hole');await h.wait(800);await h.form('Remove Selected Step');const s=await h.stepsNow(s=>s.n===3,75000,'n=3');await h.until(()=>!h.labels().includes('Drill Dowel Hole'),30000,'row removed');return h.json([s,h.labels()])")
step("A14 Undo restores","h.click('Undo');const s=await h.stepsNow(s=>s.n===4,75000,'n=4');return h.json(s)")
step("A15 Inspection shows the selected step","h.click('Cut Lap Joint');await h.wait(800);h.click('Inspection');await h.until(()=>/ID: lap-joint-cut/.test(document.body.innerText),75000,'inspection');const w=[...document.querySelectorAll('input[aria-label=Width]')][0];h.ok(w&&Math.abs(+w.value-0.3)<1e-6,'width '+(w&&w.value));return 'ok'")
step("A16 Inspection edit Width 0.3->0.1 changes volume","const w=document.querySelector('input[aria-label=Width]');h.setInput(w,0.1);const s=await h.stepsNow(s=>Math.abs(s.vol-window.__v0)>1e-4,75000,'volume change after width edit');await h.until(()=>Math.abs(+document.querySelector('input[aria-label=Width]').value-0.1)<1e-6,75000,'width value kept');return h.json(s)")
